<?php require_once '../conexao.php';require_once '../includes/rbac.php';require_once '../includes/flash.php';exigirCargo(['profissional']);$pid=(int)($_SESSION['profissional_id']??0);if(!$pid){flash('error','Seu usuário ainda não está vinculado a um profissional.');header('Location: ../logout.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$data=$_POST['data']??'';$hora=$_POST['horario']??'';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$data)||$data<date('Y-m-d')||!preg_match('/^\d{2}:\d{2}$/',$hora))flash('error','Informe data e horário válidos.');else try{$s=$pdo->prepare('INSERT IGNORE INTO disponibilidades(profissional_id,data,horario) VALUES(?,?,?)');$s->execute([$pid,$data,$hora.':00']);flash($s->rowCount()?'success':'warning',$s->rowCount()?'Disponibilidade adicionada.':'Esse horário já está cadastrado.');}catch(Throwable $e){flash('error','Não foi possível salvar o horário.');}header('Location:index.php');exit;}$s=$pdo->prepare("SELECT a.*,TIMESTAMPDIFF(YEAR,a.nascimento,CURDATE()) idade FROM agendamentos a WHERE a.profissional_id=? AND a.data>=CURDATE() AND a.status<>'cancelado' ORDER BY a.data,a.horario LIMIT 100");$s->execute([$pid]);$ag=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM disponibilidades WHERE profissional_id=? AND data>=CURDATE() ORDER BY data,horario');$s->execute([$pid]);$disp=$s->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Minha agenda | Aura</title><link rel="stylesheet" href="../css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="side-logo"><img src="../img/logo-aura-oficial.png"></a><small>PROFISSIONAL</small><a class="active">Minha agenda</a><a href="#horarios">Meus horários</a><a href="../logout.php">Sair</a></aside><main class="dashboard"><div class="dash-head"><div><p class="eyebrow">ÁREA DO PROFISSIONAL</p><h1>Minha agenda</h1><p class="muted"><?=htmlspecialchars($_SESSION['usuario_nome'])?></p></div></div><?php mostrarFlash();?><section class="dash-card" id="horarios"><h2>Adicionar disponibilidade</h2><form method="post" class="filter-bar"><label>Data<input type="date" name="data" min="<?=date('Y-m-d')?>" required></label><label>Horário<input type="time" name="horario" required></label><button class="btn">Adicionar horário</button></form><div class="chips"><?php foreach($disp as $d):?><span><?=date('d/m',strtotime($d['data']))?> · <?=substr($d['horario'],0,5)?></span><?php endforeach;?></div></section><section class="dash-card"><h2>Próximos pacientes</h2><div class="table-wrapper flat"><table><thead><tr><th>Data</th><th>Hora</th><th>Paciente</th><th>Idade</th><th>Telefone</th><th>Serviço</th><th>Status</th></tr></thead><tbody><?php foreach($ag as $a):?><tr><td><?=date('d/m/Y',strtotime($a['data']))?></td><td><?=substr($a['horario'],0,5)?></td><td><?=htmlspecialchars($a['nome'])?></td><td><?=$a['idade']?> anos</td><td><?=htmlspecialchars($a['telefone'])?></td><td><?=htmlspecialchars($a['servico'])?></td><td><span class="status <?=$a['status']?>"><?=$a['status']?></span></td></tr><?php endforeach;?></tbody></table></div></section></main></div><script src="../js/app.js"></script></body></html>
